# -*- coding: utf-8 -*-
# Auto-generated by Antigravity Agent for task: создай график синусоиды sin(x) на отрезке [0, 2pi] и сохрани картинку

import os
import math
from PIL import Image, ImageDraw

# Определение рабочей директории и пути сохранения
BASE_DIR = os.path.dirname(os.path.abspath(__file__)) if "__file__" in locals() else os.getcwd()
media_dir = os.path.join(BASE_DIR, "media")
os.makedirs(media_dir, exist_ok=True)
output_path = os.path.join(media_dir, "sine_wave.png")

# Параметры изображения
width, height = 800, 500
image = Image.new("RGB", (width, height), color=(25, 27, 34))
draw = ImageDraw.Draw(image)

# Отступы и рабочая область графика
margin_left, margin_right = 70, 50
margin_top, margin_bottom = 60, 60
plot_w = width - margin_left - margin_right
plot_h = height - margin_top - margin_bottom

origin_x = margin_left
origin_y = margin_top + plot_h // 2
amplitude_scale = plot_h / 2.5

# Сетка и метки по оси Y
for i in range(5):
    y_val = 1.0 - i * 0.5
    y_pixel = origin_y - int(y_val * amplitude_scale)
    draw.line([(margin_left, y_pixel), (margin_left + plot_w, y_pixel)], fill=(45, 48, 58), width=1)
    draw.text((margin_left - 45, y_pixel - 6), f"{y_val:+.1f}", fill=(160, 165, 180))

# Сетка и метки по оси X
x_ticks = [
    (0, "0"),
    (math.pi / 2, "π/2"),
    (math.pi, "π"),
    (3 * math.pi / 2, "3π/2"),
    (2 * math.pi, "2π")
]
for x_val, label in x_ticks:
    x_pixel = origin_x + int((x_val / (2 * math.pi)) * plot_w)
    draw.line([(x_pixel, margin_top), (x_pixel, margin_top + plot_h)], fill=(45, 48, 58), width=1)
    draw.text((x_pixel - 8, origin_y + (plot_h // 2) + 15), label, fill=(160, 165, 180))

# Оси координат (X и Y)
draw.line([(origin_x, margin_top), (origin_x, margin_top + plot_h)], fill=(200, 205, 215), width=2)
draw.line([(origin_x, origin_y), (origin_x + plot_w, origin_y)], fill=(200, 205, 215), width=2)

# Заголовок графика
draw.text((width // 2 - 95, 20), "График функции y = sin(x) на [0, 2π]", fill=(240, 245, 255))

# Расчет точек синусоиды
num_steps = 400
points = []
for step in range(num_steps + 1):
    x = (2 * math.pi * step) / num_steps
    y = math.sin(x)
    px = origin_x + int((x / (2 * math.pi)) * plot_w)
    py = origin_y - int(y * amplitude_scale)
    points.append((px, py))

# Отрисовка кривой синусоиды
draw.line(points, fill=(0, 210, 255), width=3)

# Сохранение результата
image.save(output_path)
print(f"График успешно создан и сохранен в: {output_path}")